//! fn-parse acceptance, run over fixtures/parse/*.eml (200 labelled messages generated by
//! fixtures/parse/generate.py: invented senders, never real mail). The labels sidecar of each
//! message says what the parser must find. The precision and recall bar is read from
//! docs/CONSTANTS.md (CODE_EXTRACT_MIN); no threshold is typed in this file.
use std::path::PathBuf;

use parse::{analyse, parse_invite, sanitise_html, sign_in_decision, Analysis};
use regex::Regex;
use serde_json::Value;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

fn code_extract_min() -> f64 {
    let t = std::fs::read_to_string(root().join("docs/CONSTANTS.md")).expect("docs/CONSTANTS.md");
    let line = t.lines().find(|l| l.contains("CODE_EXTRACT_MIN")).expect("CODE_EXTRACT_MIN row");
    let cell = line.split('|').nth(2).expect("value cell").trim();
    cell.split_whitespace().next().unwrap().parse().expect("a number")
}

struct Fixture {
    id: String,
    a: Analysis,
    labels: Value,
}

fn load() -> Vec<Fixture> {
    let dir = root().join("fixtures/parse");
    let mut ids: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| e.ok())
        .filter_map(|e| e.file_name().to_str().and_then(|n| n.strip_suffix(".eml").map(String::from)))
        .collect();
    ids.sort();
    ids.into_iter()
        .map(|id| {
            let bytes = std::fs::read(dir.join(format!("{id}.eml"))).unwrap();
            let labels: Value = serde_json::from_str(&std::fs::read_to_string(dir.join(format!("{id}.labels.json"))).unwrap()).unwrap();
            let a = analyse(&bytes).unwrap_or_else(|e| panic!("{id}: {e}"));
            Fixture { id, a, labels }
        })
        .collect()
}

#[test]
fn there_are_200_labelled_messages() {
    let f = load();
    assert_eq!(f.len(), 200, "fixtures/parse must hold 200 .eml files");
    let tracker_labelled = f.iter().filter(|x| x.labels["tracker_count"].as_u64().unwrap() > 0).count();
    assert!(tracker_labelled >= 30, "the set must carry tracker cases, found {tracker_labelled}");
}

#[test]
fn sanitised_output_has_no_script_handler_or_remote_image() {
    let on_attr = Regex::new(r"(?i)\son\w+\s*=").unwrap();
    let remote_src = Regex::new(r#"(?i)\ssrc\s*=\s*["']?\s*(https?:)?//"#).unwrap();
    let other = Regex::new(r"(?i)srcset|\sbackground\s*=|url\(|<iframe|<object|<embed|<link|<meta|<base|<form|<svg|javascript:").unwrap();
    let mut bad = Vec::new();
    let mut with_html = 0;
    for f in load() {
        let Some(s) = &f.a.safe_html else { continue };
        with_html += 1;
        let h = &s.html;
        if h.to_lowercase().contains("<script") || on_attr.is_match(h) || remote_src.is_match(h) || other.is_match(h) {
            bad.push(f.id.clone());
        }
    }
    println!("sanitiser: {with_html} messages with an HTML part, {} unsafe", bad.len());
    assert!(bad.is_empty(), "unsafe sanitised output in: {bad:?}");
    assert!(with_html > 0);
}

#[test]
fn every_remote_image_is_replaced_and_counted_as_a_tracker() {
    let mut wrong = Vec::new();
    for f in load() {
        let want = f.labels["tracker_count"].as_u64().unwrap() as u32;
        if f.a.trackers_blocked != want {
            wrong.push(format!("{}: want {want}, got {}", f.id, f.a.trackers_blocked));
        }
        if want >= 1 {
            assert!(f.a.trackers_blocked >= 1, "{}: labelled tracker, reported none", f.id);
        }
    }
    assert!(wrong.is_empty(), "tracker counts differ: {wrong:?}");
}

fn prf(tp: usize, fp: usize, fneg: usize) -> (f64, f64) {
    let p = if tp + fp == 0 { 1.0 } else { tp as f64 / (tp + fp) as f64 };
    let r = if tp + fneg == 0 { 1.0 } else { tp as f64 / (tp + fneg) as f64 };
    (p, r)
}

#[test]
fn login_code_precision_and_recall_meet_the_constant() {
    let min = code_extract_min();
    let (mut tp, mut fp, mut fneg) = (0, 0, 0);
    let mut miss = Vec::new();
    for f in load() {
        let want = f.labels["code"].as_str().map(String::from);
        let got = f.a.login.code.clone();
        match (&want, &got) {
            (Some(w), Some(g)) if w == g => tp += 1,
            (Some(_), Some(_)) => { fp += 1; fneg += 1; miss.push(format!("{}: want {want:?} got {got:?}", f.id)); }
            (Some(_), None) => { fneg += 1; miss.push(format!("{}: want {want:?} got none", f.id)); }
            (None, Some(_)) => { fp += 1; miss.push(format!("{}: want none got {got:?}", f.id)); }
            (None, None) => {}
        }
    }
    let (p, r) = prf(tp, fp, fneg);
    println!("codes: tp={tp} fp={fp} fn={fneg} precision={p:.4} recall={r:.4} min={min}");
    assert!(p >= min && r >= min, "precision {p:.4} recall {r:.4} below {min}: {miss:?}");
}

#[test]
fn sign_in_link_precision_and_recall_meet_the_constant() {
    let min = code_extract_min();
    let (mut tp, mut fp, mut fneg) = (0, 0, 0);
    let mut miss = Vec::new();
    for f in load() {
        let want: Vec<String> = f.labels["links"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
        let got = &f.a.login.links;
        for w in &want {
            if got.contains(w) { tp += 1 } else { fneg += 1; miss.push(format!("{}: missed {w}", f.id)) }
        }
        for g in got {
            if !want.contains(g) { fp += 1; miss.push(format!("{}: extra {g}", f.id)) }
        }
    }
    let (p, r) = prf(tp, fp, fneg);
    println!("links: tp={tp} fp={fp} fn={fneg} precision={p:.4} recall={r:.4} min={min}");
    assert!(p >= min && r >= min, "precision {p:.4} recall {r:.4} below {min}: {miss:?}");
}

#[test]
fn calendar_invites_are_read() {
    let mut wrong = Vec::new();
    let mut seen = 0;
    for f in load() {
        let want = &f.labels["invite"];
        match (want.is_null(), &f.a.invite) {
            (true, None) => {}
            (true, Some(_)) => wrong.push(format!("{}: invite found in a message without one", f.id)),
            (false, None) => wrong.push(format!("{}: invite missed", f.id)),
            (false, Some(i)) => {
                seen += 1;
                let mut bad = Vec::new();
                if i.method != want["method"].as_str().unwrap() { bad.push("method") }
                if i.uid != want["uid"].as_str().unwrap() { bad.push("uid") }
                if i.summary != want["summary"].as_str().unwrap() { bad.push("summary") }
                if i.organizer.as_deref() != want["organizer"].as_str() { bad.push("organizer") }
                if i.all_day != want["all_day"].as_bool().unwrap() { bad.push("all_day") }
                if i.start.utc_ms != want["start_utc_ms"].as_i64() { bad.push("start_utc_ms") }
                if i.start.local.as_deref() != want["start_local"].as_str() { bad.push("start_local") }
                if i.start.tzid.as_deref() != want["tzid"].as_str() { bad.push("tzid") }
                if i.location.as_deref() != want["location"].as_str() { bad.push("location") }
                if !bad.is_empty() { wrong.push(format!("{}: {bad:?}", f.id)) }
            }
        }
    }
    assert!(seen >= 20, "expected 20 invites, read {seen}");
    assert!(wrong.is_empty(), "{wrong:?}");
}

#[test]
fn quoted_text_boundaries_are_found() {
    let mut wrong = Vec::new();
    let mut with_boundary = 0;
    for f in load() {
        let q = &f.labels["quoted"];
        if q.is_null() {
            let in_quote_family = f.labels["category"].as_str().unwrap().starts_with("quoted");
            if f.a.text_quote_start.is_some() {
                wrong.push(format!("{}: boundary found where none is labelled ({})", f.id, f.labels["category"]));
            } else if in_quote_family { /* the "none" decoys: correct */ }
            continue;
        }
        with_boundary += 1;
        let visible = q["visible_contains"].as_str().unwrap();
        let folded = q["folded_contains"].as_str().unwrap();
        if q["kind"] == "text" {
            let marker = q["marker"].as_str().unwrap();
            match f.a.text_quote_start {
                None => wrong.push(format!("{}: text boundary missed", f.id)),
                Some(o) => {
                    let (head, tail) = f.a.message.text.split_at(o);
                    if !tail.starts_with(marker) || !head.contains(visible) || head.contains(folded) || !tail.contains(folded) {
                        wrong.push(format!("{}: boundary at the wrong place", f.id));
                    }
                }
            }
        } else {
            let s = f.a.safe_html.as_ref().unwrap();
            match s.quote_offset {
                None => wrong.push(format!("{}: html boundary missed", f.id)),
                Some(o) => {
                    let (head, tail) = s.html.split_at(o);
                    if !head.contains(visible) || head.contains(folded) || !tail.contains(folded) {
                        wrong.push(format!("{}: html boundary at the wrong place", f.id));
                    }
                }
            }
        }
    }
    assert!(with_boundary >= 20);
    assert!(wrong.is_empty(), "{wrong:?}");
}

// ---- unit cases for the pieces ----

#[test]
fn script_and_handlers_are_removed_from_a_hostile_snippet() {
    let s = sanitise_html(r#"<p onclick="x()">hi</p><script>alert(1)</script><img src="https://t.example.net/p.gif" onerror="y()"><a href="javascript:z()">l</a>"#);
    assert!(!s.html.to_lowercase().contains("<script"), "{}", s.html);
    assert!(!s.html.contains("onclick") && !s.html.contains("onerror") && !s.html.contains("javascript:"), "{}", s.html);
    // Changed by the lead's ruling of 2026-11-11 (round 5): an image with no stated size is a PICTURE, so its address is now kept for the
    // view's "Load once", in `data-whoosh-src` only (never fetched before the owner's click). Before: the address had to be absent.
    assert_eq!(s.html.matches("https://t.example.net").count(), 1, "{}", s.html);
    assert!(s.html.contains("data-whoosh-src=\"https://t.example.net/p.gif\""), "{}", s.html);
    assert_eq!(s.trackers_blocked, 1);
    assert!(s.html.contains("cid:whoosh-blocked"));
}

#[test]
fn cid_images_are_kept_and_not_counted() {
    let s = sanitise_html(r#"<p>x</p><img src="cid:logo123">"#);
    assert_eq!(s.trackers_blocked, 0);
    assert!(s.html.contains("cid:logo123"));
}

#[test]
fn an_all_day_invite_has_a_date_and_no_instant() {
    let ics = "BEGIN:VCALENDAR\r\nMETHOD:REQUEST\r\nBEGIN:VEVENT\r\nUID:u1\r\nDTSTART;VALUE=DATE:20261112\r\nSUMMARY:Off\\, site\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";
    let i = parse_invite(ics).unwrap();
    assert!(i.all_day);
    assert_eq!(i.start.local.as_deref(), Some("2026-11-12"));
    assert_eq!(i.start.utc_ms, None);
    assert_eq!(i.summary, "Off, site");
}

#[test]
fn the_decision_question_is_the_typed_yes_no_one() {
    let bytes = std::fs::read(root().join("fixtures/parse/001.eml")).unwrap();
    let a = analyse(&bytes).unwrap();
    let (state, qs) = sign_in_decision(&a);
    assert_eq!(qs.len(), 1);
    match &qs[0] {
        contracts::DecisionQuestion::Noul { id, prompt } => {
            assert_eq!(id, parse::SIGN_IN_QUESTION_ID);
            assert_eq!(prompt, parse::SIGN_IN_QUESTION_PROMPT);
        }
        other => panic!("expected a Noul question, got {other:?}"),
    }
    assert!(state.text.contains(&a.message.subject));
}

